-- PostgreSQL schema. GENERATED by scripts/export_schema.py. All times UTC.

CREATE TABLE businesses (
	id SERIAL NOT NULL, 
	business_name VARCHAR(255) NOT NULL, 
	type VARCHAR(20) NOT NULL, 
	subscription_status VARCHAR(20) NOT NULL, 
	created_at TIMESTAMP WITHOUT TIME ZONE NOT NULL, 
	PRIMARY KEY (id), 
	CONSTRAINT ck_businesses_type CHECK (type IN ('pharmacy', 'manufacturer', 'distributor'))
);


CREATE TABLE products (
	id SERIAL NOT NULL, 
	product_name VARCHAR(255) NOT NULL, 
	nafdac_number VARCHAR(32) NOT NULL, 
	nafdac_key VARCHAR(32) NOT NULL, 
	manufacturer VARCHAR(255) NOT NULL, 
	category VARCHAR(20) NOT NULL, 
	pack_sizes VARCHAR(255), 
	status VARCHAR(20) NOT NULL, 
	expiry_info VARCHAR(255), 
	barcode VARCHAR(64), 
	photo_url VARCHAR(500), 
	is_sample BOOLEAN NOT NULL, 
	created_at TIMESTAMP WITHOUT TIME ZONE NOT NULL, 
	updated_at TIMESTAMP WITHOUT TIME ZONE NOT NULL, 
	PRIMARY KEY (id), 
	CONSTRAINT ck_products_category CHECK (category IN ('drug', 'food', 'cosmetic', 'water', 'herbal')), 
	CONSTRAINT ck_products_status CHECK (status IN ('active', 'recalled', 'suspended')), 
	UNIQUE (nafdac_key)
);

CREATE INDEX ix_products_product_name ON products (product_name);

CREATE TABLE users_admin (
	id SERIAL NOT NULL, 
	email VARCHAR(255) NOT NULL, 
	password_hash VARCHAR(255) NOT NULL, 
	role VARCHAR(20) NOT NULL, 
	created_at TIMESTAMP WITHOUT TIME ZONE NOT NULL, 
	PRIMARY KEY (id), 
	UNIQUE (email)
);


CREATE TABLE wa_sessions (
	phone_hash VARCHAR(64) NOT NULL, 
	language VARCHAR(5), 
	state VARCHAR(20) NOT NULL, 
	updated_at TIMESTAMP WITHOUT TIME ZONE NOT NULL, 
	PRIMARY KEY (phone_hash)
);


CREATE TABLE checks (
	id SERIAL NOT NULL, 
	phone_hash VARCHAR(64) NOT NULL, 
	input_type VARCHAR(30) NOT NULL, 
	input_text VARCHAR(200), 
	verdict VARCHAR(20) NOT NULL, 
	product_id INTEGER, 
	language VARCHAR(5) NOT NULL, 
	created_at TIMESTAMP WITHOUT TIME ZONE NOT NULL, 
	PRIMARY KEY (id), 
	FOREIGN KEY(product_id) REFERENCES products (id)
);

CREATE INDEX ix_checks_created_at ON checks (created_at);
CREATE INDEX ix_checks_phone_hash ON checks (phone_hash);
CREATE INDEX ix_checks_verdict ON checks (verdict);

CREATE TABLE recalled_batches (
	id SERIAL NOT NULL, 
	product_id INTEGER NOT NULL, 
	batch_no VARCHAR(64) NOT NULL, 
	reason TEXT, 
	created_at TIMESTAMP WITHOUT TIME ZONE NOT NULL, 
	PRIMARY KEY (id), 
	FOREIGN KEY(product_id) REFERENCES products (id)
);

CREATE INDEX ix_recalled_batches_product_id ON recalled_batches (product_id);

CREATE TABLE reports (
	id SERIAL NOT NULL, 
	product_id INTEGER, 
	photo_url VARCHAR(500), 
	location_text VARCHAR(255), 
	market_name VARCHAR(255), 
	description TEXT, 
	status VARCHAR(20) NOT NULL, 
	created_at TIMESTAMP WITHOUT TIME ZONE NOT NULL, 
	PRIMARY KEY (id), 
	CONSTRAINT ck_reports_status CHECK (status IN ('pending', 'reviewed', 'confirmed_fake')), 
	FOREIGN KEY(product_id) REFERENCES products (id)
);


